import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = 0
    for x in op:
        if x == 'C':
            opp_c += 1
    opp_d = n - opp_c
    opp_rate = opp_c / n

    # Endgame: once cooperation is well established, keep it; otherwise exploit.
    if n >= 95:
        if opp_rate > 0.9:
            return 'C'
        if opp_rate < 0.4:
            return 'D'
        return 'D' if rng.random() < 0.7 else 'C'

    # Strong defectors: punish, but keep a small repair channel.
    if n >= 6 and opp_rate < 0.18:
        if rng.random() < 0.95:
            return 'D'
        return 'C'

    # Confirmed cooperators: harvest most of the time, but keep them cooperating.
    if n >= 8 and opp_rate > 0.9:
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    # Recent behavior.
    look = min(6, n)
    rec_op = op[-look:]
    rec_me = me[-look:]
    rec_opp_c = 0
    for x in rec_op:
        if x == 'C':
            rec_opp_c += 1
    rec_my_c = 0
    for x in rec_me:
        if x == 'C':
            rec_my_c += 1
    rec_opp_d = look - rec_opp_c

    # Run lengths at the tail.
    run_d = 0
    for x in reversed(op):
        if x == 'D':
            run_d += 1
        else:
            break
    run_c = 0
    for x in reversed(op):
        if x == 'C':
            run_c += 1
        else:
            break

    last_op = op[-1]
    last_me = me[-1]

    # Reciprocate a defection, but short punishment with a fast path back.
    if last_op == 'D':
        # Opponent usually cooperative: forgive a single blip.
        if opp_rate > 0.75 and run_d == 1:
            return 'C'
        # We have been punishing a while: try a conciliatory move to break DD.
        if run_c == 0 and last_me == 'D' and run_d >= 2 and run_d <= 4:
            if rng.random() < 0.35:
                return 'C'
        # Punish sustained defection.
        if run_d >= 3:
            return 'D' if rng.random() < 0.9 else 'C'
        # Single defection from a mixed opponent: retaliate.
        return 'D'

    # Opponent cooperated.
    # Preserve established mutual cooperation.
    if last_me == 'C' and opp_rate > 0.5:
        # Occasionally probe very cooperative partners early/mid game.
        if opp_rate > 0.85 and n < 90 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # We defected last round and opponent still cooperated.
    if last_me == 'D':
        # If opponent is forgiving and cooperative, exploit moderately.
        if opp_rate > 0.7:
            # Alternate exploitation with cooperation to keep them around.
            if rng.random() < 0.45:
                return 'D'
            return 'C'
        # Against mixed opponents, return to cooperation to rebuild.
        if rng.random() < 0.7:
            return 'C'
        return 'D'

    # Default fallback: reciprocate.
    if last_op == 'C':
        return 'C'
    return 'D'
